import 'package:flutter/material.dart';
import '../models.dart'; import '../services/loader.dart'; import '../services/store.dart'; import 'player.dart';
Widget channelTile(BuildContext c,Channel ch,VoidCallback? after)=>ListTile(leading:SizedBox(width:48,child:ch.logo.isEmpty?const Icon(Icons.tv):Image.network(ch.logo,errorBuilder:(_,__,___)=>const Icon(Icons.tv))),title:Text(ch.name,maxLines:1,overflow:TextOverflow.ellipsis),subtitle:Text(ch.group),onTap:()async{await Navigator.push(c,MaterialPageRoute(builder:(_)=>PlayerScreen(ch:ch)));after?.call();});
class ChannelsScreen extends StatefulWidget{const ChannelsScreen({super.key});@override State<ChannelsScreen> createState()=>_S();}
class _S extends State<ChannelsScreen>{List<Channel> all=[];bool loading=true;String? err,group;String q='';@override void initState(){super.initState();_load();}Future<void> _load()async{final s=Store.active;if(s==null){if(mounted)setState((){loading=false;err='أضف مصدر أول';});return;}final cached=Store.cachedChannels(s.id);if(cached.isNotEmpty&&mounted)setState((){all=cached;loading=false;});try{final r=await loadChannels(s);await Store.saveChannels(s.id,r);if(mounted)setState((){all=r;loading=false;err=null;});}catch(e){if(mounted)setState((){err=cached.isNotEmpty?null:'$e';loading=false;});}}@override Widget build(BuildContext context){final groups=all.map((e)=>e.group).toSet().toList()..sort();final list=all.where((c)=>(group==null||c.group==group)&&c.name.toLowerCase().contains(q.toLowerCase())).toList();return Scaffold(appBar:AppBar(title:Text(Store.active?.name??'القنوات'),actions:[IconButton(tooltip:'تحديث القائمة',icon:const Icon(Icons.refresh),onPressed:(){setState((){loading=true;err=null;});_load();})]),body:loading?const Center(child:CircularProgressIndicator()):err!=null?Center(child:Padding(padding:const EdgeInsets.all(24),child:Text(err!))):Column(children:[Padding(padding:const EdgeInsets.all(8),child:TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'بحث',border:OutlineInputBorder()),onChanged:(v)=>setState(()=>q=v))),SizedBox(height:44,child:ListView(scrollDirection:Axis.horizontal,children:[Padding(padding:const EdgeInsets.all(4),child:ChoiceChip(label:const Text('الكل'),selected:group==null,onSelected:(_)=>setState(()=>group=null))),for(final g in groups)Padding(padding:const EdgeInsets.all(4),child:ChoiceChip(label:Text(g),selected:group==g,onSelected:(_)=>setState(()=>group=g)))])),Expanded(child:ListView.builder(itemCount:list.length,itemBuilder:(c,i)=>channelTile(c,list[i],null))) ]));}}
